.ledger{
  width: 100%;
}
.ledger_c{
  // width: 100%;
  background: #fff;
  border-radius: 5px;
  box-shadow: 0px 8px 20px 0px rgba(107,190,253,0.38);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 30px;

  .ledger_tit{
    display: flex;
    align-items: center;
    font-size: 24px;
    font-weight: 600;
    color: #192C7D;
    img{
      width: 18px;
      height: 18px;
      margin-left: 15px;
    }
  }
  .ledger_item{
    display: flex;
    align-items: center;
    line-height: 40px;
    color: #666;
    font-size: 14px;
    .ledger_iteml{
      background: linear-gradient(270deg, rgba(234,255,239,0) 0%, #D9FFE4 100%);
      border-radius: 4px;
      display: flex;
      align-items: center;

      img{
        // width: 18px;
        // height: 18px;
        margin: 0 10px;
      }
    }
    .ledger_iteml2{
      background: linear-gradient(270deg, rgba(255,255,255,0) 0%, #FDFADB 100%);
    }
    .ledger_itemr{
      span{
        color: #192C7D;
        font-size: 24px;
        font-weight: 600;
        margin: 0 10px 0 15px;
      }
    }
  }
}
